//! Checks cell expansion against QuPath's own output.
//!
//! Fixture generated by `parity/java/CellExpansion.java` via
//! `./parity/record.sh`, recorded through the five lines detection runs to turn
//! nuclei into cells:
//!
//! ```java
//! FloatProcessor fpEDM = new EDM().makeFloatEDM(bp, (byte)255, false);
//! fpEDM.multiply(-1);
//! double cellExpansionThreshold = -cellExpansion;
//! ImageProcessor ipLabelsCells = ipLabels.duplicate();
//! Watershed.doWatershed(fpEDM, ipLabelsCells, cellExpansionThreshold, false);
//! PolygonRoi[] roisCells = RoiLabeling.labelsToFilledROIs(ipLabelsCells, roisNuclei.size());
//! ```
//!
//! Needs no slide.
//!
//! Four checkpoints are asserted, not one, because each is a separable piece of
//! work and a single end-to-end label image would say only that something
//! disagrees:
//!
//! - `edm` — the distance map **before** the negation, compared by its bits.
//!   This is the checkpoint that catches the background argument: with `0` it
//!   would be zero off the nuclei instead of on them.
//! - `surface` — the same after `multiply(-1)`, which is what the flood sees.
//! - `cellLabels` — what the flood leaves, one label per cell.
//! - `cytoplasmLabels` — the cell labels with every nucleus pixel zeroed.
//!
//! And `cellAreas` alongside them, which is the number D-008's 10% overlap test
//! actually turns on. A label image can agree everywhere and still give a
//! different area, because the area is of the *filled traced polygon* rather
//! than of the labelled pixels.

use qupath_watershed::Connectivity;
use qupath_watershed::{DistanceMap, cell_areas, expand_labels, label_image};

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/CellExpansion.json")
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

fn floats(text: &str) -> Vec<f32> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

fn ints(text: &str) -> Vec<i64> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("integer"))
        .collect()
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions and counts are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

#[test]
fn matches_qupath_cell_expansion() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));
    let (cases, _) = between(&text, "\"cases\": [", "\n  ]\n}", 0);

    let mut count = 0usize;
    let mut at = 0usize;
    let mut distances = DistanceMap::new();
    while let Some(start) = cases[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(cases, "\"name\": \"", "\"", from);
        let (width, next) = scalar(cases, "width", next);
        let (height, next) = scalar(cases, "height", next);
        let (expansion, next) = scalar(cases, "cellExpansion", next);
        let (nucleus_count, next) = scalar(cases, "nucleusCount", next);
        let (cell_count, next) = scalar(cases, "cellCount", next);
        let (areas_text, next) = between(cases, "\"cellAreas\": [", "]", next);
        let (nuclei_text, next) = between(cases, "\"nuclei\": [", "]", next);
        let (nucleus_labels_text, next) = between(cases, "\"nucleusLabels\": [", "]", next);
        let (edm_text, next) = between(cases, "\"edm\": [", "]", next);
        let (surface_text, next) = between(cases, "\"surface\": [", "]", next);
        let (cell_labels_text, next) = between(cases, "\"cellLabels\": [", "]", next);
        let (cytoplasm_text, next) = between(cases, "\"cytoplasmLabels\": [", "]", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let nucleus_count = index(nucleus_count);
        let mask: Vec<u8> = ints(nuclei_text)
            .into_iter()
            .map(|v| u8::try_from(v).expect("mask byte"))
            .collect();
        let their_nucleus_labels = floats(nucleus_labels_text);
        let their_edm = floats(edm_text);
        let their_surface = floats(surface_text);
        let their_cell_labels = floats(cell_labels_text);
        let their_cytoplasm = floats(cytoplasm_text);
        let their_areas = ints(areas_text);

        assert_eq!(mask.len(), width * height, "{name}: nucleus mask");

        // The nucleus labels the call site already holds. Recomputing them here
        // rather than reading the fixture's would let a labelling bug cancel an
        // expansion bug, so they are asserted first and then used.
        let mut labels = vec![0.0f32; width * height];
        let found = label_image(
            &mask.iter().map(|&v| f32::from(v)).collect::<Vec<_>>(),
            &mut labels,
            width,
            127.0,
            Connectivity::Four,
        );
        assert_eq!(
            index(f64::from(found)),
            nucleus_count,
            "{name}: nucleus count"
        );
        assert_eq!(labels, their_nucleus_labels, "{name}: nucleus labels");

        // The distance map before the negation. This is the checkpoint that
        // catches the background argument.
        let mut edm = vec![0.0f32; width * height];
        distances.make_float_edm_from(&mask, &mut edm, width, 255);
        assert_eq!(
            edm.iter().map(|v| v.to_bits()).collect::<Vec<_>>(),
            their_edm.iter().map(|v| v.to_bits()).collect::<Vec<_>>(),
            "{name}: EDM"
        );

        // The expansion itself, in place, leaving the negated surface in `edm`.
        let mut cells = labels.clone();
        let mut surface = vec![0.0f32; width * height];
        expand_labels(&mask, &mut cells, &mut surface, width, expansion);
        assert_eq!(
            surface.iter().map(|v| v.to_bits()).collect::<Vec<_>>(),
            their_surface
                .iter()
                .map(|v| v.to_bits())
                .collect::<Vec<_>>(),
            "{name}: negated surface"
        );
        assert_eq!(cells, their_cell_labels, "{name}: cell labels");

        // The cytoplasm image the call site builds next.
        let cytoplasm: Vec<f32> = cells
            .iter()
            .zip(&labels)
            .map(|(&cell, &nucleus)| if nucleus != 0.0 { 0.0 } else { cell })
            .collect();
        assert_eq!(cytoplasm, their_cytoplasm, "{name}: cytoplasm labels");

        // The filled areas, which is the number the overlap test turns on.
        let areas = cell_areas(&cells, width, nucleus_count);
        assert_eq!(areas.len(), index(cell_count), "{name}: cell count");
        let recorded: Vec<Option<u32>> =
            their_areas.iter().map(|&v| u32::try_from(v).ok()).collect();
        assert_eq!(areas, recorded, "{name}: cell areas");

        count += 1;
    }

    assert_eq!(count, 10, "every recorded case should be checked");
}
